// Package claude is the Go port of ~/.claude/statusline.mjs plus the herdr
// side effects (terminal labels and limits.json) that the poke UI reads.
//
// Render must reproduce the Node script byte for byte; the goldens in testdata
// are generated by running the real script (see testdata/gen-golden.sh).
package claude

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"os"
	"os/exec"
	"os/user"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"herdr-poke/internal/labels"
	"herdr-poke/internal/state"
)

// Limit windows, in minutes, as Claude Code names them in rate_limits.
const (
	fiveHourMinutes = 300
	sevenDayMinutes = 10080
)

// Input mirrors the statusline JSON Claude Code (2.1.x) sends on stdin. Only
// the fields the statusline uses are listed.
type Input struct {
	SessionID     string        `json:"session_id"`
	Model         Model         `json:"model"`
	Effort        Effort        `json:"effort"`
	Cwd           string        `json:"cwd"`
	Workspace     Workspace     `json:"workspace"`
	ContextWindow ContextWindow `json:"context_window"`
	RateLimits    *RateLimits   `json:"rate_limits"`
	OutputStyle   OutputStyle   `json:"output_style"`
	Cost          Cost          `json:"cost"`
}

type Model struct {
	ID          string `json:"id"`
	DisplayName string `json:"display_name"`
}

type Effort struct {
	Level string `json:"level"`
}

type Workspace struct {
	CurrentDir string `json:"current_dir"`
}

type ContextWindow struct {
	Size         float64 `json:"context_window_size"`
	CurrentUsage *Usage  `json:"current_usage"` // null before the first API call
}

type Usage struct {
	InputTokens              float64 `json:"input_tokens"`
	CacheCreationInputTokens float64 `json:"cache_creation_input_tokens"`
	CacheReadInputTokens     float64 `json:"cache_read_input_tokens"`
}

type RateLimits struct {
	FiveHour *RateLimit `json:"five_hour"`
	SevenDay *RateLimit `json:"seven_day"`
}

type RateLimit struct {
	UsedPercentage *float64 `json:"used_percentage"` // nil: not reported
	ResetsAt       float64  `json:"resets_at"`       // epoch seconds
}

type OutputStyle struct {
	Name string `json:"name"`
}

type Cost struct {
	TotalDurationMs float64 `json:"total_duration_ms"`
}

// Env is everything besides stdin that the Node script reads from its
// surroundings: homedir(), process.cwd(), Date.now(), ~/.claude.json,
// CLAUDE_CODE_AUTO_COMPACT_WINDOW and the git binary.
type Env struct {
	Home              string
	Cwd               string // process cwd, used when stdin has neither cwd nor workspace.current_dir
	Now               time.Time
	ClaudeJSONPath    string
	AutoCompactWindow float64 // CLAUDE_CODE_AUTO_COMPACT_WINDOW; <= 0 means unset or invalid
	// Git reports the branch (or short SHA when detached) of dir and whether the
	// worktree is dirty. ok=false means "not a repo": no git segment.
	Git func(dir string) (branch string, dirty bool, ok bool)
}

// EnvFromOS builds the Env of the running process.
func EnvFromOS() Env {
	home := homeDir()
	cwd, _ := os.Getwd()
	return Env{
		Home:              home,
		Cwd:               cwd,
		Now:               time.Now(),
		ClaudeJSONPath:    filepath.Join(home, ".claude.json"),
		AutoCompactWindow: parseAutoCompactWindow(os.Getenv("CLAUDE_CODE_AUTO_COMPACT_WINDOW")),
		Git:               gitInfo,
	}
}

func homeDir() string {
	if h, err := os.UserHomeDir(); err == nil {
		return h
	}
	if u, err := user.Current(); err == nil {
		return u.HomeDir
	}
	return ""
}

// parseAutoCompactWindow mirrors `Number(env)` being finite and > 0; anything
// else (unset, empty, junk, zero, negative, infinite) yields 0 = "not set".
func parseAutoCompactWindow(s string) float64 {
	v, err := strconv.ParseFloat(strings.TrimSpace(s), 64)
	if err != nil || math.IsNaN(v) || math.IsInf(v, 0) || v <= 0 {
		return 0
	}
	return v
}

// ---- rendering ----

const reset = "\x1b[0m"

const (
	bold = "\x1b[1m"
	dim  = "\x1b[2m"

	gray          = "\x1b[90m"
	red           = "\x1b[31m"
	green         = "\x1b[32m"
	yellow        = "\x1b[33m"
	magenta       = "\x1b[35m"
	brightCyan    = "\x1b[96m"
	brightMagenta = "\x1b[95m"
	blue          = "\x1b[34m"
)

func paint(s string, codes ...string) string {
	return strings.Join(codes, "") + s + reset
}

// jsRound is JavaScript's Math.round: halves round toward +Infinity (Go's
// math.Round rounds them away from zero, which differs for negatives).
func jsRound(x float64) float64 {
	f := math.Floor(x)
	if x-f >= 0.5 {
		return f + 1
	}
	return f
}

func clamp(x, lo, hi float64) float64 {
	return math.Min(hi, math.Max(lo, x))
}

// Render returns the statusline text, without a trailing newline.
func Render(in Input, env Env) string {
	var segs []string

	// 1. account (email · org)
	if s, ok := accountSegment(env.ClaudeJSONPath); ok {
		segs = append(segs, s)
	}

	// 2. cwd (~ shorthand)
	rawCwd := in.Cwd
	if rawCwd == "" {
		rawCwd = in.Workspace.CurrentDir
	}
	if rawCwd == "" {
		rawCwd = env.Cwd
	}
	cwd := rawCwd
	if strings.HasPrefix(rawCwd, env.Home) { // sic: also matches /Users/xavier for /Users/x, like the original
		cwd = "~" + rawCwd[len(env.Home):]
	}
	segs = append(segs, paint(cwd, brightCyan, bold))

	// 3. git branch + dirty marker
	if env.Git != nil {
		if ref, dirty, ok := env.Git(rawCwd); ok {
			if dirty {
				segs = append(segs, paint(ref, yellow)+paint("●", yellow))
			} else {
				segs = append(segs, paint(ref, green))
			}
		}
	}

	// 4. model : effort
	if m := in.Model.DisplayName; m != "" {
		s := paint(m, magenta, bold)
		if eff := in.Effort.Level; eff != "" {
			s += paint(":"+eff, magenta)
		}
		segs = append(segs, s)
	}

	// 5. context used %
	if pct, ok := ctxPct(in, env); ok {
		col := red
		if pct < 50 {
			col = green
		} else if pct < 80 {
			col = yellow
		}
		segs = append(segs, paint(fmt.Sprintf("ctx %d%%", pct), col))
	}

	// 6. rate limits (5h / 7d)
	if rl := in.RateLimits; rl != nil {
		nowS := float64(env.Now.Unix())
		var parts []string
		if s, ok := windowSegment(rl.FiveHour, "5h", nowS); ok {
			parts = append(parts, s)
		}
		if s, ok := windowSegment(rl.SevenDay, "7d", nowS); ok {
			parts = append(parts, s)
		}
		if len(parts) > 0 {
			segs = append(segs, strings.Join(parts, "  "))
		}
	}

	// 7. output style, only when not "default"
	if style := in.OutputStyle.Name; style != "" && style != "default" {
		segs = append(segs, paint(style, brightMagenta, bold))
	}

	// 8. session elapsed time
	if ms := in.Cost.TotalDurationMs; ms > 0 {
		s := math.Floor(ms / 1000)
		h := math.Floor(s / 3600)
		m := math.Floor(math.Mod(s, 3600) / 60)
		var t string
		switch {
		case h > 0:
			t = fmt.Sprintf("%dh %dm", int64(h), int64(m))
		case m > 0:
			t = fmt.Sprintf("%dm", int64(m))
		default:
			t = fmt.Sprintf("%ds", int64(s))
		}
		segs = append(segs, paint(t, gray))
	}

	return strings.Join(segs, paint(" | ", dim))
}

func accountSegment(path string) (string, bool) {
	b, err := os.ReadFile(path)
	if err != nil {
		return "", false
	}
	var cfg struct {
		OAuthAccount *struct {
			EmailAddress     string `json:"emailAddress"`
			OrganizationName string `json:"organizationName"`
		} `json:"oauthAccount"`
	}
	if json.Unmarshal(b, &cfg) != nil || cfg.OAuthAccount == nil || cfg.OAuthAccount.EmailAddress == "" {
		return "", false
	}
	parts := []string{paint(cfg.OAuthAccount.EmailAddress, gray)}
	if org := cfg.OAuthAccount.OrganizationName; org != "" {
		parts = append(parts, paint(org, blue))
	}
	return strings.Join(parts, paint(" · ", dim)), true
}

// ctxPct is the context used %, measured against the window Claude Code
// actually auto-compacts at rather than the raw model window (see the long
// comment in statusline.mjs). CLAUDE_CODE_AUTO_COMPACT_WINDOW always wins.
func ctxPct(in Input, env Env) (int, bool) {
	cw := in.ContextWindow
	if cw.CurrentUsage == nil || cw.Size == 0 {
		return 0, false
	}
	u := cw.CurrentUsage
	used := u.InputTokens + u.CacheCreationInputTokens + u.CacheReadInputTokens

	window := cw.Size
	switch {
	case env.AutoCompactWindow > 0:
		window = env.AutoCompactWindow
	case in.Model.ID == "claude-sonnet-5":
		window = 967_000
	case strings.Contains(strings.ToLower(in.Model.ID), "[1m]"):
		window = 400_000 // best known approximation for other 1M models
	}
	window = math.Min(window, cw.Size)

	// The float64() conversion forbids fusing the multiply into jsRound's
	// subtraction (FMA on arm64): 99000/200000*100 is exactly 49.5, and a fused
	// x*100-49 would give 0.4999… and round down, unlike JavaScript.
	pct := float64(used / window * 100)
	return int(clamp(jsRound(pct), 0, 100)), true
}

func windowSegment(w *RateLimit, label string, nowS float64) (string, bool) {
	if w == nil || w.UsedPercentage == nil {
		return "", false
	}
	p := jsRound(*w.UsedPercentage)
	col := green
	if p >= 80 {
		col = red
	} else if p >= 50 {
		col = yellow
	}
	filled := int(clamp(jsRound(p/20), 0, 5))
	bar := strings.Repeat("▰", filled) + strings.Repeat("▱", 5-filled)
	return paint(fmt.Sprintf("%s %s %d%%", label, bar, int64(p)), col) + countdown(w.ResetsAt, nowS), true
}

// countdown is " (1d 2h 3m)" in dim, or "" once the reset time has passed.
func countdown(resetsAt, nowS float64) string {
	left := resetsAt - nowS
	if left <= 0 {
		return ""
	}
	d := math.Floor(left / 86400)
	h := math.Floor(math.Mod(left, 86400) / 3600)
	m := math.Floor(math.Mod(left, 3600) / 60)
	var parts []string
	if d > 0 {
		parts = append(parts, fmt.Sprintf("%dd", int64(d)))
	}
	if h > 0 {
		parts = append(parts, fmt.Sprintf("%dh", int64(h)))
	}
	parts = append(parts, fmt.Sprintf("%dm", int64(m)))
	return paint(" ("+strings.Join(parts, " ")+")", dim)
}

// ---- git ----

const gitTimeout = 2 * time.Second

func runGit(dir string, args ...string) (string, bool) {
	ctx, cancel := context.WithTimeout(context.Background(), gitTimeout)
	defer cancel()
	cmd := exec.CommandContext(ctx, "git", append([]string{"-C", dir}, args...)...)
	var out bytes.Buffer
	cmd.Stdout = &out                      // stderr stays nil (/dev/null)
	cmd.WaitDelay = 200 * time.Millisecond // a grandchild holding the pipe must not outlive the timeout
	if err := cmd.Run(); err != nil {
		return "", false
	}
	return strings.TrimSpace(out.String()), true
}

// gitInfo is the real Env.Git: symbolic-ref (else the short SHA for a detached
// HEAD) plus `status --porcelain`, exactly the commands the Node script runs.
func gitInfo(dir string) (branch string, dirty bool, ok bool) {
	ref, ok := runGit(dir, "symbolic-ref", "--short", "HEAD")
	if !ok {
		if ref, ok = runGit(dir, "rev-parse", "--short", "HEAD"); !ok {
			return "", false, false
		}
	}
	status, ok := runGit(dir, "status", "--porcelain")
	if !ok {
		return "", false, false
	}
	return ref, status != "", true
}

// ---- side effects ----

// labelsFrom is what goes to herdr-core labels. A model without an effort
// param yields poke.effort="" so a stale value from the previous model is
// removed; with no model nothing is touched.
func labelsFrom(in Input, env Env) map[string]string {
	kv := map[string]string{}
	if m := in.Model.DisplayName; m != "" {
		kv["poke.model"] = m
		kv["poke.effort"] = in.Effort.Level
	}
	if pct, ok := ctxPct(in, env); ok {
		kv["poke.ctx"] = strconv.Itoa(pct)
	}
	return kv
}

// limitsFrom is the claude entry of limits.json. Windows that are not
// reported, or whose reset time is not in the future, are left out so a stale
// percentage can never be shown. ok=false when there is nothing to record.
func limitsFrom(in Input, now time.Time) (state.ProviderLimits, bool) {
	if in.RateLimits == nil {
		return state.ProviderLimits{}, false
	}
	var ws []state.Window
	add := func(minutes int, w *RateLimit) {
		if w == nil || w.UsedPercentage == nil || int64(w.ResetsAt) <= now.Unix() {
			return
		}
		ws = append(ws, state.Window{Minutes: minutes, Used: *w.UsedPercentage, ResetsAt: int64(w.ResetsAt)})
	}
	add(fiveHourMinutes, in.RateLimits.FiveHour)
	add(sevenDayMinutes, in.RateLimits.SevenDay)
	if len(ws) == 0 {
		return state.ProviderLimits{}, false
	}
	return state.ProviderLimits{Windows: ws, Updated: now.Unix()}, true
}

// ---- entry point ----

func parseInput(raw []byte) (Input, error) {
	if len(raw) == 0 {
		raw = []byte("{}") // the original does `JSON.parse(raw || "{}")`
	}
	var in Input
	err := json.Unmarshal(raw, &in)
	var typeErr *json.UnmarshalTypeError
	if errors.As(err, &typeErr) {
		err = nil // one wrongly typed field must not blank the whole line
	}
	return in, err
}

func safeRender(in Input, env Env) (out string) {
	defer func() {
		if recover() != nil {
			out = "\n"
		}
	}()
	return Render(in, env)
}

func sideEffects(in Input, env Env) {
	defer func() { _ = recover() }()
	if kv := labelsFrom(in, env); len(kv) > 0 {
		terminal := os.Getenv("HC_TERMINAL_ID")
		if owner := labels.ForegroundOwner(terminal, "claude"); owner > 0 {
			_ = labels.Set(terminal, labels.Telemetry(owner, "claude", in.SessionID, kv))
		}
	}
	if l, ok := limitsFrom(in, env.Now); ok {
		_, _ = state.MergeLimits("claude", l)
	}
}

// Run is `herdr-poke statusline`: print the statusline for the JSON on stdin,
// then record labels and limits. It never fails Claude Code: the exit code is
// always 0, and unparseable input prints an empty line. The line is written
// before any side effect so label/limit I/O cannot delay it.
func Run(stdin io.Reader, stdout io.Writer) int {
	raw, _ := io.ReadAll(stdin)
	in, err := parseInput(raw)
	if err != nil {
		_, _ = io.WriteString(stdout, "\n")
		return 0
	}
	env := EnvFromOS()
	_, _ = io.WriteString(stdout, safeRender(in, env))
	sideEffects(in, env)
	return 0
}
